import lote08_base as B
L = []
SAB = "Sabiston Tratado de Cirugía 21.ª ed. (2021)"
SCH = "Schwartz Principios de Cirugía 11.ª ed. (2019)"
HAR = "Harrison Principios de Medicina Interna 21.ª ed. (2022)"
